using System;
using System.IO;

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportToCsv = false, string csvFilePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // New functionality: Export report to CSV if requested
        if (exportToCsv)
        {
            if (string.IsNullOrEmpty(csvFilePath))
            {
                csvFilePath = "report_output.csv";
            }

            try
            {
                using (StreamWriter writer = new StreamWriter(csvFilePath))
                {
                    // Write CSV header
                    writer.WriteLine("Field,Value");

                    // Write report data as CSV rows
                    // Assuming SummaryReport has a method or properties that can be iterated or converted to key-value pairs
                    // For demonstration, we assume report has a method GetKeyValuePairs() or similar.
                    // If not, you may need to adapt this part based on the actual structure of SummaryReport.
                    var data = report.GetReportData(); // Hypothetical method to get report data as a list of key-value pairs

                    foreach (var item in data)
                    {
                        writer.WriteLine($"{item.Key},{item.Value}");
                    }
                }

                Console.WriteLine($"Report successfully exported to {csvFilePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
            }
        }
    }
}

